function renderInspector(){const n=selected;if(!n)return;const cells=[['ID oficial',n.officialId||n.id],['Grupo MOC',n.group],['Tipo MOC',missing(n.type)],['Categoria',missing(n.kind)],['Pai',missing(n.parent)],['Ocorrência',missing(n.occur)],['Tamanho',missing(n.length)],['XPath',n.xpath||'Não confirmado'],['XSD',missing(n.xsdType)],['Tabela Oracle','Somente sugestão (aba Oracle)']];
 $('#inspector').innerHTML=`<span class="tag blue">${safe(n.id)}</span><h3>${safe(n.tag)}</h3><p class="footnote">${safe(n.description||'Descrição indisponível')}</p><div class="inspect-path">${safe(n.xpath||'XPath não determinado')}</div>${cells.map(([a,b])=>`<div class="keyvalue"><b>${safe(a)}</b><span>${safe(b)}</span></div>`).join('')}<h4>Observação do MOC</h4><p class="footnote">${safe(missing(n.observation))}</p><button class="btn" id="copyXPath">Copiar XPath</button> <button class="btn primary" id="inspectorPrint">Selecionar para impressão</button>`;$('#inspectorPrint').onclick=()=>selectForPrint([n.key]);$('#copyXPath').onclick=()=>{if(n.xpath)navigator.clipboard?.writeText(n.xpath).catch(()=>{});};}
const dictionaryFields=[['id','ID'],['tag','Campo'],['group','Grupo MOC'],['description','Descrição'],['parent','Pai'],['kind','Ele'],['type','Tipo MOC'],['occur','Ocor.'],['length','Tamanho'],['xpath','XPath'],['observation','Observação'],['xsdType','Tipo XSD']];
