function renderDictColumns(){const panel=$('#dictColumnPanel');panel.innerHTML=dictionaryFields.map(([field,label])=>`<label><input type="checkbox" data-dict-column="${safe(field)}" ${visibleDict.has(field)?'checked':''}> ${safe(label)}</label>`).join('');panel.querySelectorAll('[data-dict-column]').forEach(el=>el.onchange=()=>{if(el.checked)visibleDict.add(el.dataset.dictColumn);else if(visibleDict.size>1)visibleDict.delete(el.dataset.dictColumn);else el.checked=true;renderDictionary()});}
