function diagramSubset(){const group=$('#diagramGroup').value||groupOptions()[0],root=byKey.get($('#diagramFocus').value),max=Number($('#diagramDepth').value)||3,all=nodes.filter(n=>n.group===group),ids=new Set(all.map(n=>n.id)),start=root?[root]:all.filter(n=>!ids.has(n.parentRef)),queue=start.map(n=>({n,d:0})),seen=new Set(),items=[];for(let i=0;i<queue.length&&items.length<350;i++){const x=queue[i];if(seen.has(x.n.key))continue;seen.add(x.n.key);items.push(x);if(x.d>=max)continue;for(const ch of children.get(x.n.id)||[])if(ch.group===group&&!seen.has(ch.key))queue.push({n:ch,d:x.d+1});}return {items,total:all.length,group,limited:queue.length>items.length||(!root&&all.length>350)};}
