 for(const card of cards){const col=heights[0]<=heights[1]?0:1;const y=heights[col],height=102+card.arr.length*56;placements.push({card,col,y,height});heights[col]+=height+18;}
 const h=Math.max(...heights)+12;
 const content=placements.map(({card,col,y,height})=>{
 const x=cardX[col],p=card.parent,tag=p?.tag||'Documento NF-e',id=p?.id||'Raiz',count=card.arr.length;
 const title=`${id} · ${tag}`;
 const head=`<g ${p?`data-node-key="${safe(p.key)}"`:''} class="diagram-node"><rect x="${x}" y="${y}" width="${cardW}" height="${height}" rx="12" fill="white" stroke="#9bbfce" stroke-width="1.5"/><rect x="${x}" y="${y}" width="${cardW}" height="76" rx="12" fill="#dcefe6"/><rect x="${x}" y="${y+63}" width="${cardW}" height="13" fill="#dcefe6"/><text x="${x+16}" y="${y+27}" font-size="20" font-weight="bold" fill="#173c53">${safe(title.slice(0,47))}</text><text x="${x+16}" y="${y+48}" font-size="13" fill="#3d677c">Grupo/subgrupo pai · ${count} filhos exibidos · parte ${card.part}/${card.count}</text><text x="${x+16}" y="${y+65}" font-size="11.5" fill="#527386">${safe((p?.xpath||'Origem do grupo selecionado').slice(0,82))}</text></g>`;
 const lines=card.arr.map((n,k)=>{const yy=y+84+k*56;const sub=String(n.description||'Sem descrição na seleção').slice(0,57);return `<g class="diagram-node ${selected?.key===n.key?'chosen':''}" data-node-key="${safe(n.key)}"><rect x="${x+10}" y="${yy}" width="${cardW-20}" height="48" rx="6" fill="${structural(n)?'#eaf5ed':k%2?'#f0f5fa':'#f6f9fc'}" stroke="#d4e3ec"/><text x="${x+21}" y="${yy+20}" font-size="16" font-weight="bold" fill="#154965">${safe((n.id+'  '+n.tag).slice(0,42))}</text><text x="${x+cardW-24}" y="${yy+20}" text-anchor="end" font-size="12.5" fill="#346981">${safe(n.occur||'—')}</text><text x="${x+21}" y="${yy+38}" font-size="12.5" fill="#496d81">${safe(sub)}</text><title>${safe((n.description||'')+'\nPai: '+(n.parent||'—'))}</title></g>`}).join('');
 return head+lines;
 }).join('');
