function printTreeNode(n,depth,visited,find,visible){
 if(visited.has(n.key)||depth>32||!visible.has(n.key))return '';
 const kids=printSelection.children.get(n.key)||[],hasKids=kids.length>0,open=find?true:printTreeOpen.has(n.key),state=printSelection.stateNode(n.key),struct=structural(n);
 return `<div class="print-tree-node" role="treeitem" aria-level="${depth+1}"><div class="print-tree-line ${struct?'print-tree-struct':''}" style="--level:${Math.min(depth,20)}"><button type="button" class="print-tree-caret" data-tree-expand="${safe(n.key)}" aria-label="${open?'Recolher':'Expandir'} ${safe(n.tag)}" ${hasKids?'':'disabled'}>${hasKids?(open?'▾':'▸'):'·'}</button><input type="checkbox" data-tree-key="${safe(n.key)}" ${state==='all'?'checked':''} data-state="${state}" aria-label="Selecionar ${safe(n.id)} ${safe(n.tag)}"><span class="print-tree-id">${safe(n.id)}</span><b>${safe(n.tag)}</b><small>${kids.length?kids.length+' filhos':''} ${safe(n.occur||'')}</small></div>${open?kids.map(k=>printTreeNode(printSelection.map.get(k),depth+1,new Set([...visited,n.key]),find,visible)).join(''):''}</div>`;
}
function printSearchVisible(find){const visible=new Set();if(!find)return new Set(nodes.map(n=>n.key));for(const n of nodes){if([n.id,n.tag,n.group,n.description,n.xpath].some(x=>String(x||'').toLowerCase().includes(find)))for(const k of [...printSelection.ancestors(n.key),n.key])visible.add(k)}return visible;}
function renderPrintTree(){if(!printSelection)return;const find=$('#printTreeSearch').value.trim().toLowerCase(),visible=printSearchVisible(find),groups=groupOptions();let selectedGroups=0,partialGroups=0,structuralCount=0;
 for(const g of groups){const st=printSelection.stateGroup(g);if(st==='all')selectedGroups++;if(st==='partial')partialGroups++;}
 for(const n of nodes)if(printSelection.selected.has(n.key)&&structural(n))structuralCount++;
 $('#selectionCount').innerHTML=`<strong>${printSelection.count()} / ${nodes.length}</strong><span>campos selecionados · ${selectedGroups} grupos completos · ${partialGroups} parciais · ${structuralCount} subgrupos</span>`;
 $('#printTree').innerHTML=groups.map(g=>{const rows=printSelection.groups.get(g)||[];if(!rows.some(n=>visible.has(n.key)))return '';const state=printSelection.stateGroup(g),opened=find||printTreeOpen.has('group:'+g);return `<section class="print-tree-group"><div class="print-tree-group-head"><button class="print-tree-caret" data-tree-expand="group:${safe(g)}" title="Expandir grupo">${opened?'▾':'▸'}</button><input type="checkbox" data-tree-group="${safe(g)}" ${state==='all'?'checked':''} data-state="${state}" aria-label="Selecionar todo grupo ${safe(g)}"><strong>${safe(g)} — ${safe(groupLabel(g))}</strong><small>${rows.length} nós</small></div>${opened?printSelection.tree(g).map(n=>printTreeNode(n,0,new Set(),find,visible)).join(''):''}</section>`}).join('')||'<p>Nenhum campo localizado nesta base.</p>';
 $('#printTree').querySelectorAll('input[type=checkbox][data-state=partial]').forEach(el=>el.indeterminate=true);
 $('#printTree').querySelectorAll('[data-tree-key]').forEach(el=>el.onchange=()=>{printSelection.changeNode(el.dataset.treeKey,el.checked);renderPrintTree();printable()});
 $('#printTree').querySelectorAll('[data-tree-group]').forEach(el=>el.onchange=()=>{printSelection.changeGroup(el.dataset.treeGroup,el.checked);renderPrintTree();printable()});
 $('#printTree').querySelectorAll('[data-tree-expand]').forEach(el=>el.onclick=()=>{const k=el.dataset.treeExpand;printTreeOpen.has(k)?printTreeOpen.delete(k):printTreeOpen.add(k);renderPrintTree()});
}
