function buildPrintSelectionData(){const chosen=$('#printScope').value==='selection'?new Set(printSelection.selected):new Set(nodes.filter(n=>selectedPrintGroups().includes(n.group)).map(n=>n.key));const context=$('#printScope').value==='selection'?printSelection.contextKeys():new Set(chosen);const rows=nodes.filter(n=>chosen.has(n.key)),all=nodes.filter(n=>context.has(n.key));return {chosen,context,rows,all,groups:[...new Set(rows.map(n=>n.group))]};}
