function selectedPrintGroups(){const scope=$('#printScope').value;if(scope==='group')return [$('#printGroup').value].filter(Boolean);if(scope==='multi')return [...$$('#printGroupsMulti input:checked')].map(x=>x.value);return groupOptions()}
function printDiagramBlocks(group,scope){const rows=scope?scope.all.filter(n=>n.group===group):nodes.filter(n=>n.group===group),parents=new Map();for(const n of rows){const p=n.parentRef||'Raiz';if(!parents.has(p))parents.set(p,[]);parents.get(p).push(n)}const blocks=[];for(const [parent,a] of parents){const label=byId.get(parent)?.tag||'Documento / raiz';for(let i=0;i<a.length;i+=12){const chunk=a.slice(i,i+12),part=Math.floor(i/12)+1,count=Math.ceil(a.length/12);blocks.push(`<article class="print-block"><div class="print-block-header"><b>${safe(label)} <span style="font-size:8pt">(${safe(parent)})</span></b><small>${chunk.length} elementos · Parte ${part}/${count}${part>1?' — continuação do grupo pai':''}</small></div><div class="print-connector">↓ relação pai → filhos do catálogo</div><table><thead><tr><th>Identificador e tag</th><th>Ocorrência / descrição</th></tr></thead><tbody>${chunk.map(n=>`<tr><td>${safe(n.id)} · ${safe(n.tag)}</td><td>${safe(n.occur||'—')}<small style="display:block;color:#536e80">${safe($('#printDetail').value==='short'?'':(n.description||'Descrição não informada'))}</small></td></tr>`).join('')}</tbody></table>${part<count?'<p class="print-continued">Este grupo continua no bloco seguinte.</p>':''}</article>`)} }return `<div class="print-blocks">${blocks.join('')}</div>`;}
function printHierarchyList(group,scope){const rs=scope?scope.all.filter(n=>n.group===group):nodes.filter(n=>n.group===group),lookup=new Map(nodes.map(n=>[n.id,n]));let rows=rs.map(n=>{let d=0,p=n.parentRef,seen=new Set([n.id]);while(p&&lookup.has(p)&&!seen.has(p)&&d<7){seen.add(p);d++;p=lookup.get(p).parentRef}return `<tr><td>${safe(n.id)}</td><td style="padding-left:${3+d*5}mm;border-left:${Math.max(1,d)}px solid #a5c4ce">${'&rsaquo; '.repeat(Math.min(d,7))}<b>${safe(n.tag)}</b></td><td>${safe(n.parent||'—')}</td><td>${safe(n.occur||'—')}</td><td>${safe(n.description||'—')}</td></tr>`}).join('');return `<table class="moc-table print-tree-table"><thead><tr><th>ID</th><th>Elemento</th><th>Pai</th><th>Ocorrência</th><th>Descrição</th></tr></thead><tbody>${rows}</tbody></table>`;}
function printOracleModel(){return `<section class="print-section"><h2>Modelagem relacional Oracle — PROPOSTA TÉCNICA</h2><p>Entidades e PK/FK são sugestões de projeto; não são tabelas do MOC nem um banco de dados real.</p><div class="print-der">${oracle.map(e=>`<article><h3>${safe(e.n)}</h3><ul>${e.f.map(f=>`<li>${safe(f)}</li>`).join('')}</ul></article>`).join('')}</div><h3>Relacionamentos sugeridos</h3><p>NF_DOCUMENTO 1:N NF_ITEM · NF_ITEM 1:N NF_ITEM_TRIBUTO · NF_DOCUMENTO 1:N NF_REFERENCIA · NF_DOCUMENTO 1:1 NF_TOTAL</p></section>`}
function printHistoryPage(){return `<section class="print-section"><h2>Histórico e alterações de versões</h2>${diffs.length?`<table class="moc-table"><thead><tr><th>Identificador</th><th>Situação</th><th>Alterações</th></tr></thead><tbody>${diffs.map(d=>`<tr><td>${safe(d.id)}</td><td>${safe(d.status)}</td><td>${safe(JSON.stringify(d.changes||d.new||d.old))}</td></tr>`).join('')}</tbody></table>`:'<p>Não existe comparativo confirmado carregado nesta instalação. Nenhuma alteração foi presumida.</p>'}</section>`}
function printDictionaryPage(groups,scope){const rows=scope?scope.rows:nodes.filter(n=>groups.includes(n.group));return `<section class="print-section"><h2>Dicionário de dados — catálogo selecionado</h2><table class="moc-table"><thead><tr><th>ID</th><th>Campo</th><th>Grupo</th><th>Descrição</th><th>Tipo</th><th>Ocor.</th><th>XPath</th></tr></thead><tbody>${rows.map(n=>`<tr>${[n.id,n.tag,n.group,n.description,n.type,n.occur,n.xpath||'Não confirmado'].map(td).join('')}</tr>`).join('')}</tbody></table></section>`}
function printMocPage(group,obs,mode='official',scope){const rows=scope?scope.rows.filter(n=>n.group===group):nodes.filter(n=>n.group===group);return `<section class="print-group"><h3>Grupo ${safe(group)} — ${safe(groupLabel(group))}</h3><p class="print-source">${mode==='official'?'Ordem editorial do catálogo': 'Hierarquia baseada na referência Pai · subgrupos indentados'} · n/i = não importado na seleção · n/d = não disponível na extração</p>${mode==='official'?mocTable(rows,obs):mocHierarchyTable(scope?selectedHierarchyEntries(group,scope):mocHierarchyEntries(group,'',true),mode,false,obs,scope?.chosen)}</section>`}
function printable(){const types={integrated:'Relatório técnico integrado',official:'Leiaute do MOC — dez colunas',group:'Relatório por grupo',diagram:'Diagrama hierárquico completo', 'diagram-group':'Diagramas por grupo',dictionary:'Dicionário de dados',oracle:'Modelagem Oracle',diff:'Alterações entre versões'};
 const type=$('#printType').value,scope=buildPrintSelectionData(),groups=scope.groups,date=new Date().toLocaleDateString('pt-BR'),scopeRows=scope.rows;let sections='';
 const coverage=data.metadata?.status||'cobertura não informada',font=Number($('#printFont').value)||10,obs=$('#printObservations').checked;
 const meta=`<p class="print-page-meta">Data: ${date} · Fonte: ${safe(data.metadata?.source||'não confirmada')} · Estado: ${safe(coverage)} · Registros nesta seleção: ${scopeRows.length}</p>`;
 if($('#printCover').checked)sections+=`<div class="print-cover"><div class="coverline"></div><p>DOCUMENTAÇÃO TÉCNICA INDEPENDENTE · NF-e / NFC-e</p><h1>${safe(types[type])}</h1><h2>Explorador de leiaute, XML/XSD e dados fiscais</h2><p>Gerado em ${date}</p><p class="print-note"><b>Base:</b> ${safe(coverage)}. O conteúdo reflete somente os ${scopeRows.length} registros selecionados do catálogo disponível. Não corresponde necessariamente ao MOC integral vigente.</p><p>Fonte oficial de referência: https://moc.sped.fazenda.pr.gov.br/NFe_NFCe/Leiaute.html</p></div>`;
 if($('#printSummary').checked)sections+=`<section><h2>Sumário e escopo</h2>${meta}<p><b>Tipo:</b> ${safe(types[type])} · <b>Grupos:</b> ${safe(groups.join(', ')||'nenhum')} · <b>Registros:</b> ${scopeRows.length}</p><p>${groups.map(g=>`Grupo ${safe(g)} — ${safe(groupLabel(g))}`).join('<br>')}</p><p>Relações XML oriundas das referências pai-filho do catálogo. O DER Oracle está identificado como proposta e exige validação técnica.</p></section>`;
 const wantBlocks=['diagram','diagram-group','integrated','group'].includes(type)&&$('#printDiagrams').checked;
 if(wantBlocks){for(const g of groups){sections+=`<section class="print-section"><h2>Diagrama compacto — Grupo ${safe(g)}</h2><p class="print-source">${safe(groupLabel(g))} · visualização paginável, sem redução da estrutura para caber numa única página</p>${$('#printDiagramFormat').value==='tree'?printHierarchyList(g,scope):printDiagramBlocks(g,scope)}</section>`;}}
 if(['official','group','integrated'].includes(type)){sections+=`<section class="print-section"><h2>Leiaute do MOC — campos presentes no catálogo</h2>${meta}${groups.map(g=>printMocPage(g,obs,$('#printMocMode').value,scope)).join('')}</section>`;}
 if(type==='dictionary'||$('#printDictionary').checked)sections+=printDictionaryPage(groups,scope);
 if(type==='oracle'||$('#printOracle').checked)sections+=printOracleModel();
 if(type==='diff'||$('#printHistory').checked)sections+=printHistoryPage();
 if(!scopeRows.length){sections='<section class="print-section"><h2>Nenhum elemento selecionado</h2><p>Marque campos na árvore de seleção para gerar seu relatório.</p></section>';}
 const size=$('#pageSize').value,orient=$('#pageOrient').value,margin=$('#printMargin').value,color=$('#printColor').value;
 const print=document.querySelector('#printDocument');print.innerHTML=`<div class="print-page ${color==='bw'?'bw':''}" style="font-size:${font}pt">${sections}</div>`;
 const old=$('#printRule');if(old)old.remove();const rule=document.createElement('style');rule.id='printRule';rule.textContent=`@page{size:${size} ${orient};margin:${margin}mm ${margin}mm ${Number(margin)+4}mm ${margin}mm;@bottom-left{content:'Explorador NF-e/NFC-e · ${size}';font-size:7pt;color:#526779}@bottom-right{content:'Página ' counter(page);font-size:7pt;color:#526779}}@media print{.print-page{font-size:${font}pt!important}.print-page .moc-table{font-size:${Math.max(7,font-2)}pt}}`;document.head.append(rule);
 $('#btnDoPrint').disabled=!scopeRows.length;$('#printPreview').innerHTML=`<div class="print-preview-head"><h3>Pré-visualização pronta</h3><p>${safe(types[type])} · ${groups.length} grupos · ${scopeRows.length} registros · ${size} ${orient==='landscape'?'paisagem':'retrato'} · ${font} pt · ${color==='bw'?'preto e branco':'colorido'}</p></div><p class="footnote">A quantidade de páginas é calculada pelo navegador ao salvar. Os blocos são separados por pai e as tabelas repetem o cabeçalho.</p>`;
 const preview=$('#printPreviewRender');const first=print.querySelector('.print-group,.print-section,.print-cover');preview.innerHTML=`<div class="preview-sheet">${first?first.outerHTML:'<p>Sem conteúdo.</p>'}<p style="font-size:11px;color:#688098">Prévia da primeira seção. O PDF inclui todas as demais seções selecionadas.</p></div>`;
}
function go(view){$$('.view').forEach(e=>e.classList.toggle('active',e.id==='view-'+view));$$('.navlink').forEach(e=>e.classList.toggle('active',e.dataset.view===view));window.scrollTo({top:0,behavior:'instant'});if(view==='diagrama')requestAnimationFrame(renderDiagram);if(view==='impressao')requestAnimationFrame(renderPrintTree);}
async function fetchServer(){if(location.protocol==='file:')return;try{const pairs=[['/api/catalogo','./data/catalogo_atual.json'],['/api/status','./data/status.json'],['/api/historico','./data/historico.json'],['/api/diferencas','./data/ultima_diferenca.json'],['/api/xsd','./data/xsd_catalogo.json'],['/api/notificacoes','./data/notificacoes.json']];const getData=async([api,staticFile])=>{let r=await fetch(api).catch(()=>null);if(!r?.ok)r=await fetch(staticFile).catch(()=>null);if(!r?.ok)return null;const t=r.headers.get('content-type')||'';if(!t.includes('json'))return null;return r.json()};const [a,b,c,d,e,f]=await Promise.all(pairs.map(getData));if(a?.nodes?.length)normalize(a);if(b)status=b;if(c)history=c;if(d)diffs=d.changes||[];if(e)xsdData=e;if(f)notifications=f;renderXsd();renderUpdates();}catch(e){console.info('Backend ou catálogo estático não disponível; a seleção demonstrativa permanece visível.')}}
async function importCatalog(file){if(!file)return;try{const parsed=JSON.parse(await file.text());if(!parsed.nodes?.length)throw Error('JSON sem nós');normalize(parsed);$('#updateMessage').textContent='Catálogo carregado para esta sessão. Sincronização persistente depende do backend.';}catch(e){$('#updateMessage').textContent='Não foi possível carregar: '+e.message}}
async function requestUpdate(){const msg=$('#updateMessage');const token=prompt('Token de administração do servidor (não é armazenado):');if(!token){msg.textContent='Consulta cancelada.';return;}msg.textContent='Consultando a fonte oficial...';try{const r=await fetch('/api/atualizar',{method:'POST',headers:{'Authorization':'Bearer '+token}});const d=await r.json();msg.textContent=d.error||d.message||JSON.stringify(d);if(r.ok)await fetchServer();}catch(e){msg.textContent='Sem backend disponível. Execute python scripts/monitor.py no servidor.'}}
$$('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$$('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));
$('#searchMoc').oninput=renderMoc;$('#groupMoc').onchange=renderMoc;$('#expandMoc').onclick=()=>{mocOpen=new Set(groupOptions());mocNodeOpen=new Set(nodes.map(n=>n.key));renderMoc()};$('#collapseMoc').onclick=()=>{mocNodeOpen.clear();mocOpen=new Set(groupOptions());renderMoc()};$('#mocMode').onchange=renderMoc;
$('#searchTree').oninput=renderTree;$('#filterTree').onchange=renderTree;$('#expandTree').onclick=()=>{expanded=new Set(nodes.map(n=>n.id));renderTree()};$('#collapseTree').onclick=()=>{expanded.clear();renderTree()};$('#treeAddPrint').onclick=()=>{if(selected)selectForPrint([selected.key])};
['searchDict','filterDict','typeDict','dictSort'].forEach(x=>$('#'+x).addEventListener(x==='searchDict'?'input':'change',renderDictionary));$('#dictColumnsToggle').onclick=()=>{$('#dictColumnPanel').hidden=!$('#dictColumnPanel').hidden;renderDictColumns()};$('#dictPrintSelected').onclick=()=>{const chosen=dictionaryRows().map(n=>n.key);printSelection.all(false);for(const k of chosen)printSelection.changeNode(k,true);$('#printScope').value='selection';go('impressao');printable()};$('#exportCsv').onclick=exportCsv;$('#exportJson').onclick=exportJson;$('#exportXlsx').onclick=()=>{if(location.protocol==='file:'){alert('Para XLSX dinâmico, execute o servidor. O CSV funciona offline.');return;}window.open('/api/exportar/xlsx','_blank')};
$('#diagramGroup').onchange=()=>{diagramFocusOptions();renderDiagram()};
