 $('#zoomIn').onclick=()=>setDiagramZoom(zoom+.15);$('#zoomOut').onclick=()=>setDiagramZoom(zoom-.15);$('#zoomReset').onclick=()=>setDiagramZoom(1);
 $('#diagramCenter').onclick=()=>{const v=$('#diagramViewport');v.scrollLeft=Math.max(0,(diagramW*zoom-v.clientWidth)/2);v.scrollTop=0};
 $('#diagramFit').onclick=()=>fitDiagram(false);$('#diagramFitAll').onclick=()=>fitDiagram(true);
 $('#diagramFullscreen').onclick=()=>{const v=$('#diagramViewport');if(document.fullscreenElement)document.exitFullscreen?.();else v.requestFullscreen?.()};
 $('#diagramSidebar').onclick=()=>{const app=$('.app');app.classList.toggle('sidebar-collapsed');$('#diagramSidebar').textContent=app.classList.contains('sidebar-collapsed')?'Mostrar menu':'Recolher menu'};
 $('#diagramSearch').oninput=()=>{const query=$('#diagramSearch').value.toLowerCase().trim();if(!query)return;const a=nodes.find(n=>[n.id,n.tag,n.description,n.xpath].some(v=>String(v||'').toLowerCase().includes(query)));if(a){$('#diagramGroup').value=a.group;$('#diagramDepth').value='15';diagramFocusOptions();choose(a.key);renderDiagram();centerDiagramNode(a.key)}};
 const vp=$('#diagramViewport');let pointer=null;vp.addEventListener('pointerdown',e=>{if(e.target.closest?.('[data-node-key]'))return;pointer={x:e.clientX,y:e.clientY,l:vp.scrollLeft,t:vp.scrollTop};vp.classList.add('dragging')});window.addEventListener('pointerup',()=>{pointer=null;vp.classList.remove('dragging')});vp.addEventListener('pointermove',e=>{if(!pointer)return;vp.scrollLeft=pointer.l+pointer.x-e.clientX;vp.scrollTop=pointer.t+pointer.y-e.clientY});
 $('#svgExport').onclick=exportSvg;$('#pngExport').onclick=exportPng;
