$('#downloadSql').onclick=()=>download('modelagem_oracle_sugerida.sql',sql,'text/plain');$('#catalogInput').onchange=e=>importCatalog(e.target.files[0]);$('#btnRefresh').onclick=requestUpdate;$('#searchXsd').oninput=renderXsd;$('#diffSearch').oninput=renderDiff;$('#diffType').onchange=renderDiff;$('#diffCsv').onclick=()=>{const rows=[['ID','Situação','Alterações'],...diffs.map(d=>[d.id,d.status,JSON.stringify(d.changes||d.new||d.old)])];download('alteracoes_moc.csv','\ufeff'+rows.map(r=>r.map(csvValue).join(';')).join('\r\n'),'text/csv')};
$('#printTreeSearch').oninput=renderPrintTree;$('#printSelectAll').onclick=()=>{printSelection.all(true);renderPrintTree();printable()};$('#printClearSelection').onclick=()=>{printSelection.all(false);renderPrintTree();printable()};$('#printExpandAll').onclick=()=>{printTreeOpen=new Set([...nodes.map(n=>n.key),...groupOptions().map(g=>'group:'+g)]);renderPrintTree()};$('#printCollapseAll').onclick=()=>{printTreeOpen.clear();renderPrintTree()};printPresets=printPresetsRead();refreshPrintPresets();$('#printSavePreset').onclick=()=>{const name=$('#printPresetName').value.trim().slice(0,80);if(!name){$('#printSelectionMessage').textContent='Informe um nome para salvar.';return;}printPresets[name]={keys:[...printSelection.selected],savedAt:new Date().toISOString(),catalogVersion:data.metadata?.version||'desconhecida'};$('#printSelectionMessage').textContent=printPresetsWrite()?'Seleção salva neste navegador.':'Armazenamento local indisponível; use exportação CSV.';refreshPrintPresets();$('#printPresetList').value=name};$('#printLoadPreset').onclick=()=>{const k=$('#printPresetList').value,p=printPresets[k];if(!p)return;printSelection.reset(nodes,p.keys||[]);renderPrintTree();printable();$('#printSelectionMessage').textContent='Seleção carregada. Campos inexistentes na base atual foram ignorados.'};$('#printDeletePreset').onclick=()=>{const k=$('#printPresetList').value;if(!k)return;delete printPresets[k];printPresetsWrite();refreshPrintPresets()};$('#printSelectedCsv').onclick=()=>{const rows=buildPrintSelectionData().rows;const values=[['ID','Campo','Grupo','Descrição','Pai','Tipo','Ocorrência','XPath'],...rows.map(n=>[n.id,n.tag,n.group,n.description,n.parent,n.type,n.occur,n.xpath])];download('selecao_impressao_nfe.csv','\ufeff'+values.map(r=>r.map(csvValue).join(';')).join('\r\n'),'text/csv;charset=utf-8')};
$('#printScope').onchange=()=>{$('#printGroupsMulti').hidden=$('#printScope').value!=='multi';printable()};['printType','printGroup','pageSize','pageOrient','printFont','printMargin','printDetail','printDiagramFormat','printMocMode','printColor','printCover','printSummary','printDiagrams','printObservations','printDictionary','printOracle','printHistory'].forEach(id=>$('#'+id).onchange=printable);$('#printGroupsMulti').onchange=printable;$('#printType').onchange=()=>{if($('#printType').value==='official')$('#printMocMode').value='official';else if(['group','integrated'].includes($('#printType').value))$('#printMocMode').value='hierarchy';printable()};$('#btnPreparePrint').onclick=printable;$('#btnDoPrint').onclick=()=>{printable();window.print()};$('#btnPrintTop').onclick=()=>{go('impressao');printable()};
